"""Geographic/time coverage inventory, not a census or an absence inference."""
from pathlib import Path
import json,html,collections,re,hashlib
root=Path.cwd();base=json.loads((root/'data/evidence.json').read_text(encoding='utf-8'));research=json.loads((root/'data/research-proposals.json').read_text(encoding='utf-8'));records=base['records']+[p['record'] for p in research['proposals']]
# Editorial rectangles are audit bins, not cultural/political boundaries.
regions=[('Alaska / Beringia',-180,-130,54,85),('Northern Canada / Arctic',-130,-50,58,85),('Pacific Northwest',-135,-115,42,58),('California / Great Basin',-125,-110,32,42),('Southwest / Four Corners',-113,-102,29,42),('Plains / prairie',-115,-95,36,58),('Great Lakes',-95,-74,40,52),('Northeast / Atlantic Canada',-78,-50,40,59),('Lower Ohio / Midwest',-96,-79,34,42),('Southeast / Tidewater',-88,-74,29,38),('Florida / Gulf coast',-99,-79,24,32),('Northern Mexico / Baja',-117,-97,23,33),('Central / Southern Mexico',-106,-87,14,24),('Guatemala / Belize',-93,-87,13,19),('Honduras / El Salvador / Nicaragua',-91,-82,10,17),('Costa Rica / Panama',-86,-77,7,11),('Cuba / Bahamas',-85,-72,20,28),('Hispaniola / Puerto Rico / Jamaica',-79,-65,17,20),('Northern Lesser Antilles',-65,-59,15,19),('Southern Lesser Antilles',-63,-59,10,15),('ABC islands',-71,-68,11,13),('Colombia',-79,-67,-4,13),('Venezuela',-73,-60,0,12),('Guianas',-62,-51,0,9),('Ecuador',-82,-75,-5,2),('Peru / Western Andes',-82,-68,-19,0),('Bolivia / Central Andes',-70,-57,-24,-8),('Amazonia / inland Brazil',-74,-45,-18,5),('Eastern Brazil',-48,-34,-25,-1),('Paraguay / Southern Brazil',-63,-47,-34,-18),('Chile / Argentina midlatitudes',-76,-52,-44,-22),('Patagonia / Tierra del Fuego',-77,-53,-57,-40),('Falkland / southern islands',-62,-25,-60,-48),('Japan / Ryukyus',120,146,23,46),('Philippines / Island Southeast Asia',120,142,-10,23),('New Guinea / Bismarcks',130,156,-12,1),('Solomons / Vanuatu / New Caledonia',150,172,-24,-3),('Marianas / Palau / Carolines',130,163,0,24),('Marshall Islands / Kiribati',163,180,-5,18),('Fiji / Tonga',175,180,-25,-10),('Fiji / Tonga / Samoa east of dateline',-180,-165,-25,-10),('Societies / Cooks / Marquesas',-165,-130,-24,0),('Hawaii',-161,-154,17,24),('Rapa Nui',-112,-108,-29,-25),('Galapagos',-93,-88,-3,3)]
bins=[('Before25,000BCE',-1000000,-25000),('25,000–15,000BCE',-24999,-15000),('15,000–10,000BCE',-14999,-9999),('10,000–6,000BCE',-9998,-5999),('6,000–3,000BCE',-5998,-2999),('3,000–1,000BCE',-2998,-999),('1,000–1BCE',-998,0),('1–500CE',1,500),('501–1000CE',501,1000),('1001–1500CE',1001,1500),('1501–1700CE',1501,1700),('1701–1934CE',1701,1934)]
def coord(r):
 o=r.get('overlay');g=o.get('geometry') if o else None
 if g:return g['coordinates'] if g['type']=='Point' else None # A route crossing a box is not a local site.
 p=r.get('location');return [p['lon'],p['lat']] if p else None
def local(r):return not r.get('overlay') and r['type'] in ['occupation','occurrence'] and r.get('location')
def link(r):return '<a href="../index.html#review/'+html.escape(r['id'])+'">'+html.escape(r['title'])+'</a>'
rows=[];matrix=[]
for name,w,e,s,n in regions:
 geo=[r for r in records if (p:=coord(r)) and w<=p[0]<=e and s<=p[1]<=n];cells=[];out=[]
 for label,a,b in bins:
  rs=[r for r in geo if r['time']['start'] is not None and r['time']['start']<=b and r['time']['end']>=a];l=[r for r in rs if local(r)];c=[r for r in rs if not local(r)];out.append({'period':label,'localRecordIds':[r['id'] for r in l],'contextRecordIds':[r['id'] for r in c]})
  cells.append('<td class="'+('local' if l else 'context' if c else 'gap')+'"><details><summary>'+str(len(l))+' / '+str(len(c))+'</summary>'+('<ul>'+''.join('<li>'+link(r)+'</li>' for r in rs)+'</ul>' if rs else 'No included dated point record in this bin; not evidence of absence.')+'</details></td>')
 unresolved=[r for r in geo if r['time']['kind']=='unplaced'];matrix.append({'region':name,'bounds':[w,e,s,n],'periods':out,'unresolvedIds':[r['id'] for r in unresolved]});rows.append('<tr><th>'+name+'<br><small>'+str(len(unresolved))+' unresolved</small></th>'+''.join(cells)+'</tr>')
queue=json.loads((root/'data/intake-queue-round7.json').read_text(encoding='utf-8'))
ledger=json.loads((root/'data/temporal-review-2026-10-29.json').read_text(encoding='utf-8'))
recommendations=[
 ('First priority: local sites in thinly covered mainland regions','Colombia, Venezuela, Guianas, Ecuador, inland Brazil, northern Mexico and the Central American isthmus have broad summaries but few individually encoded dated places. Seek named sites, sample/phase chronology and public geographic precision; do not convert a continental synthesis into a settlement.'),
 ('Middle Holocene continuity','Across North America, South America and the Caribbean, arrival / early evidence and late centers are better collected than intermediate periods. Target10,000–1,000BCE transitions region by region; query repeated-use, gaps, environmental change and survey limits separately.'),
 ('Island histories after arrival','Many Pacific islands have first-settlement evidence with thin subsequent histories, especially500–1500CE and1501–1934CE. Seek site-level habitation, exchange, language-history alternatives and dated abandonment/continuity evidence. Early human absence assessments are evidence about surveys, not automatically population absence.'),
 ('North American late and colonial history','Great Lakes, prairie, northern Canada / Arctic and Northeast need more local sequences and1500–1934CE evidence. Existing Four Corners detail is not a substitute for those regions. Community identity, language and genetic ancestry must remain distinct.'),
 ('Pending latest batch','Latest Guianas, Cuba, Lesser Antilles, central South America, Venezuela, Amazonia, Brazil and Andean syntheses identify research leads. They are not all integrated facts yet. A wrong Saint Lucia citation and mismatched generated claims are quarantined; verify original studies before filling cells.'),
 ('Climate / disaster completeness','New NOAA ENSO subset starts1525CE; earlier ENSO remains an independent proxy-reconstruction research gap. Smithsonian covers Holocene eruptions, not all Pleistocene events. NOAA tsunami records are historically incomplete. Ice snapshots are North America25–1.5ka; Greenland, Pacific sea ice, ancient shorelines and navigable water need separate data. Drought/heat/cold layers currently use sourced regional findings, not continuous gridded reconstructions.'),
]
summary={'reviewedAt':'2026-10-29','recordCount':len(records),'formerlyUnplaced':280,'recoveredWindows':64,'splitWindows':5,'remainingUnplaced':sum(r['time']['kind']=='unplaced' for r in records),'method':'Point-anchor membership in overlapping editorial bounding rectangles. Local means non-overlay occupation/occurrence record, not a verified settlement census. Regional/model/other events counted separately. Line routes excluded from regional counts. Broad windows may overlap several cells without continuous presence. No zero count implies human absence. Pending intake not counted as integrated.','recommendations':recommendations,'matrix':matrix,'intakeItems':[{k:v for k,v in x.items() if k in ['id','status','reviewFlags']} for x in queue['items']]}
(root/'data/coverage-audit.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas coverage audit</title><style>body{font:15px/1.6 system-ui;background:#10242e;color:#e8eff1;padding:22px;margin:auto;max-width:1600px}a{color:#8be3dd}h1,h2{line-height:1.2}.scroll{overflow:auto;max-height:75vh}table{border-collapse:collapse;font-size:12px}td,th{padding:9px;border:1px solid #52636a;min-width:115px;vertical-align:top}thead th{position:sticky;top:0;background:#192f39}tbody th{min-width:190px;background:#192f39;text-align:left}.local{background:#1d4b4d}.context{background:#39424f}.gap{background:#142933}summary{cursor:pointer}li{margin:7px 0}small{color:#d4dee2}section{margin:25px 0}</style><a href="../index.html#map">← Atlas</a><h1>Where the collected evidence is thin</h1>'''
body+=f'<p>Chronology review: all280 original records reviewed;64 approximate source/period windows recovered,5 disjoint windows separated;{summary["remainingUnplaced"]} records remain contextual rather than dated events. {len(records)} archaeological / historical / interpretive records in this audit. Natural-hazard catalog entries are separate.</p>'
body+='<p><strong>A zero is a collection gap, not evidence that no people lived there.</strong> Matrix values are local records / regional or other context records. Broad date windows are possible context, not continuous habitation. Rows overlap deliberately; counts cannot be summed. Routes and records without point anchors are not allocated to a region.</p><p><a href="../coverage-audit.json">Structured audit</a> · <a href="../temporal-review.json">All280 chronology decisions</a> · <a href="../intake-queue-round7.json">Latest intake status</a> · <a href="../index.html#physical">Climate sources and limits</a></p>'
body+=''.join('<section><h2>'+html.escape(a)+'</h2><p>'+html.escape(b)+'</p></section>' for a,b in recommendations)
body+='<h2>Geography × time</h2><p>Expand a cell for source-linked records. Gray context alone cannot substitute for local site chronology. Unresolved counts are independent of selected year.</p><div class="scroll"><table><thead><tr><th>Region</th>'+''.join('<th>'+x[0]+'</th>' for x in bins)+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><h2>All remaining unresolved chronology</h2><p>Retained source guidance and the specific review reason are below; these records may describe methods, modern comparisons, relative constraints or language relationships rather than dated human presence.</p>'
body+=''.join('<details><summary>'+html.escape(x['title'])+'</summary><p>'+html.escape(x['originalTime']['original'])+'</p><p>'+html.escape(x['reason'])+'</p><a href="../index.html#review/'+x['id']+'">Full review and sources</a></details>' for x in ledger['items'] if x['time']['kind']=='unplaced')
(root/'docs/coverage-audit.html').write_text(body+'</html>',encoding='utf-8')
print(json.dumps({k:summary[k] for k in ['recordCount','recoveredWindows','remainingUnplaced']}))
